"""Offline Reader 7.25 unit-only correction; no API/network calls.
Run this file in the original reader source folder, with the reader closed.
Supports source files from Reader 7.23/7.24. Backups are retained automatically.
"""
import ast,base64,hashlib,json,zlib,shutil,datetime
from pathlib import Path
DATA = ""
root=Path.cwd()
patch=json.loads(zlib.decompress(base64.b64decode(DATA)))
sha=lambda text:hashlib.sha256(text.encode('utf-8')).hexdigest()
changes=[]
for item in patch:
    path=root/item['path']
    if path.exists():
        old=path.read_text(encoding='utf-8-sig')
        if sha(old)==item['after']:continue
        if 'create' in item:raise SystemExit('Unexpected existing helper; no files changed: '+str(path))
        variant=next((v for v in item['variants'] if sha(old)==v['before']),None)
        if variant is None:raise SystemExit('Source differs from Reader 7.23/7.24; no files changed: '+str(path))
        text=old
        for before,after in variant['edits']:
            if text.count(before)!=1:raise SystemExit('Patch mismatch; no files changed')
            text=text.replace(before,after,1)
    else:
        if 'create' not in item:raise SystemExit('Reader source missing: '+str(path))
        old=None;text=item['create']
    if sha(text)!=item['after']:raise SystemExit('Verification failed; no files changed')
    ast.parse(text,filename=str(path))
    changes.append((path,old,text))
if not changes:
    print('Reader 7.25 unit correction is already applied.')
else:
    backup=root/'.invoice_app'/'code_backups'/datetime.datetime.now().strftime('before_725_%Y%m%d_%H%M%S_%f')
    for path,old,text in changes:
        if old is not None:
            saved=backup/path.relative_to(root);saved.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(path,saved)
    try:
        for path,old,text in changes:path.write_text(text,encoding='utf-8',newline='\n')
    except Exception:
        for path,old,text in changes:
            if old is None:path.unlink(missing_ok=True)
            else:shutil.copy2(backup/path.relative_to(root),path)
        raise
    print('Reader 7.25 unit correction applied. Backup: '+str(backup))
    print('Restart the Python reader. If using EXE, rebuild first.')
